//! The project: its library and its elements, held as the JSON a project file holds.

use crate::json::{Map, Value};
use std::collections::BTreeMap;

pub const FORMAT: u64 = 17;

#[derive(Clone)]
pub struct Project {
    /// Top-level keys in file order; `elements` and `library` stand in place as nulls.
    pub doc: Map,
    pub elements: BTreeMap<u64, Value>,
    pub library: BTreeMap<u64, Value>,
    /// The lowest library id handed out since the project was read: ids are never handed out twice,
    /// even once what had one is gone (an undo takes it back with the rest).
    pub lib_low: u64,
}

pub const LANGS: &[&str] = &["en", "pt", "es", "sv", "cs", "fr", "nl", "de", "it"];

fn template(lang: &str) -> &'static str {
    use crate::templates as t;
    match lang {
        "pt" => t::PT,
        "es" => t::ES,
        "sv" => t::SV,
        "cs" => t::CS,
        "fr" => t::FR,
        "nl" => t::NL,
        "de" => t::DE,
        "it" => t::IT,
        _ => t::EN,
    }
}

/// Replaces the `@G<n>` placeholders of a template with GUIDs made now, the same n the same GUID.
fn fill_guids(v: &mut Value, made: &mut Vec<Option<String>>) {
    match v {
        Value::Str(s) => {
            if let Some(n) = s.strip_prefix("@G") {
                if let Ok(n) = n.parse::<usize>() {
                    if made.len() <= n {
                        made.resize(n + 1, None);
                    }
                    if made[n].is_none() {
                        made[n] = Some(crate::rand::guid());
                    }
                    *s = made[n].clone().unwrap();
                }
            }
        }
        Value::Arr(a) => a.iter_mut().for_each(|x| fill_guids(x, made)),
        Value::Obj(m) => m.items.iter_mut().for_each(|(_, x)| fill_guids(x, made)),
        _ => {}
    }
}

pub fn new_uid() -> u64 {
    crate::rand::next_u64()
}

impl Project {
    pub fn new(lang: &str) -> Project {
        let mut v = crate::json::parse(template(lang)).expect("template");
        let mut made = Vec::new();
        fill_guids(&mut v, &mut made);
        let mut p = Project::from_value(v);
        p.doc.insert("uid", Value::u(new_uid()));
        p
    }

    pub fn from_value(v: Value) -> Project {
        let mut doc = match v {
            Value::Obj(m) => m,
            _ => Map::new(),
        };
        let mut elements = BTreeMap::new();
        let mut library = BTreeMap::new();
        if let Some(Value::Obj(m)) = doc.get_mut("elements").map(std::mem::take) {
            for (k, e) in m.items {
                if let Ok(id) = k.parse::<u64>() {
                    elements.insert(id, e);
                }
            }
        }
        if let Some(Value::Obj(m)) = doc.get_mut("library").map(std::mem::take) {
            for (k, e) in m.items {
                if let Ok(id) = k.parse::<u64>() {
                    library.insert(id, e);
                }
            }
        }
        if !doc.contains("elements") {
            doc.insert("elements", Value::Null);
        }
        if !doc.contains("library") {
            doc.insert("library", Value::Null);
        }
        Project { doc, elements, library, lib_low: 1_000_000 }
    }

    pub fn to_value(&self) -> Value {
        let mut out = Map::new();
        for (k, v) in &self.doc.items {
            if k == "elements" {
                let mut m = Map::new();
                for (id, e) in &self.elements {
                    m.items.push((id.to_string(), e.clone()));
                }
                out.items.push((k.clone(), Value::Obj(m)));
            } else if k == "library" {
                let mut m = Map::new();
                for (id, e) in &self.library {
                    m.items.push((id.to_string(), e.clone()));
                }
                out.items.push((k.clone(), Value::Obj(m)));
            } else {
                out.items.push((k.clone(), v.clone()));
            }
        }
        Value::Obj(out)
    }

    pub fn to_file_string(&self) -> String {
        self.to_value().to_pretty()
    }

    // ------------------------------------------------------------ top level

    pub fn get(&self, k: &str) -> Option<&Value> {
        self.doc.get(k)
    }
    pub fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
        self.doc.get_mut(k)
    }
    pub fn name(&self) -> String {
        self.doc.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string()
    }
    pub fn language(&self) -> String {
        self.doc.get("language").and_then(|v| v.as_str()).unwrap_or("en").to_string()
    }
    /// A section of the file (`types`, `materials`…), made where the canonical order puts it.
    pub fn section_mut(&mut self, k: &str) -> &mut Map {
        if !self.doc.contains(k) {
            self.insert_top(k, Value::obj());
        }
        let v = self.doc.get_mut(k).unwrap();
        if !matches!(v, Value::Obj(_)) {
            *v = Value::obj();
        }
        v.as_obj_mut().unwrap()
    }
    pub fn section(&self, k: &str) -> Option<&Map> {
        self.doc.get(k).and_then(|v| v.as_obj())
    }
    /// Inserts a top-level key at its place in the file's order.
    pub fn insert_top(&mut self, k: &str, v: Value) {
        if self.doc.contains(k) {
            self.doc.insert(k, v);
            return;
        }
        let order = TOP_ORDER;
        let rank = |key: &str| order.iter().position(|o| *o == key).unwrap_or(usize::MAX);
        let r = rank(k);
        let pos = self.doc.items.iter().position(|(kk, _)| rank(kk) > r).unwrap_or(self.doc.items.len());
        self.doc.items.insert(pos, (k.to_string(), v));
    }
    pub fn remove_top(&mut self, k: &str) {
        self.doc.remove(k);
    }

    // ------------------------------------------------------------ ids

    pub fn next_id(&self) -> u64 {
        self.doc.get("next_id").and_then(|v| v.as_u64()).unwrap_or(100000)
    }
    pub fn alloc_id(&mut self) -> u64 {
        let mut id = self.next_id();
        while self.elements.contains_key(&id) {
            id += 1;
        }
        self.doc.insert("next_id", Value::u(id + 1));
        id
    }

    /// The lowest id the library and its parts use.
    pub fn lowest_lib_id(&self) -> u64 {
        let mut low = 1_000_000u64;
        if let Some(k) = self.library.keys().next() {
            low = low.min(*k);
        }
        fn scan(v: &Value, low: &mut u64) {
            match v {
                Value::Obj(m) => {
                    if let Some(Value::Num(n)) = m.get("id") {
                        let x = n.as_f64();
                        if x >= 900000.0 && x < 1_000_000.0 {
                            *low = (*low).min(x as u64);
                        }
                    }
                    for (_, x) in &m.items {
                        scan(x, low);
                    }
                }
                Value::Arr(a) => a.iter().for_each(|x| scan(x, low)),
                _ => {}
            }
        }
        for (k, v) in &self.doc.items {
            if k != "elements" && k != "library" {
                scan(v, &mut low);
            }
        }
        low
    }
    pub fn alloc_lib_id(&mut self) -> u64 {
        let id = self.lowest_lib_id().min(self.lib_low) - 1;
        self.lib_low = id;
        id
    }

    // ------------------------------------------------------------ elements

    pub fn el(&self, id: u64) -> Option<&Value> {
        self.elements.get(&id)
    }
    pub fn el_mut(&mut self, id: u64) -> Option<&mut Value> {
        self.elements.get_mut(&id)
    }
    pub fn category(&self, id: u64) -> Option<&str> {
        self.elements.get(&id).and_then(|e| e.get("category")).and_then(|c| c.as_str())
    }
    pub fn guid_of(&self, id: u64) -> Option<String> {
        self.elements.get(&id).and_then(|e| e.get("guid")).and_then(|g| g.as_str()).map(|s| s.to_string())
    }
    pub fn find_guid(&self, g: &str) -> Option<u64> {
        self.elements
            .iter()
            .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()) == Some(g))
            .map(|(id, _)| *id)
    }
    pub fn ids_of(&self, cat: &str) -> Vec<u64> {
        self.elements
            .iter()
            .filter(|(_, e)| e.get("category").and_then(|c| c.as_str()) == Some(cat))
            .map(|(id, _)| *id)
            .collect()
    }

    // ------------------------------------------------------------ library

    pub fn lib_find_guid(&self, g: &str) -> Option<u64> {
        self.library
            .iter()
            .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()) == Some(g))
            .map(|(id, _)| *id)
    }
    pub fn lib_find(&self, kind: &str, name: &str) -> Option<u64> {
        self.library
            .iter()
            .find(|(_, e)| {
                e.get("kind").and_then(|x| x.as_str()) == Some(kind) && e.get("name").and_then(|x| x.as_str()) == Some(name)
            })
            .map(|(id, _)| *id)
    }
    pub fn lib_guid(&self, kind: &str, name: &str) -> Option<String> {
        let id = self.lib_find(kind, name)?;
        self.library.get(&id).and_then(|e| e.get("guid")).and_then(|g| g.as_str()).map(|s| s.to_string())
    }
    /// The name of the library entry with this GUID.
    pub fn lib_name(&self, g: &str) -> Option<String> {
        let id = self.lib_find_guid(g)?;
        self.library.get(&id).and_then(|e| e.get("name")).and_then(|g| g.as_str()).map(|s| s.to_string())
    }
    pub fn lib_add(&mut self, kind: &str, name: &str) -> (u64, String) {
        let id = self.alloc_lib_id();
        let g = crate::rand::guid();
        self.library.insert(id, crate::jobj! {"kind" => kind, "name" => name, "guid" => g.clone()});
        (id, g)
    }
}

/// The order of a project file's top-level keys.
pub const TOP_ORDER: &[&str] = &[
    "format",
    "name",
    "uid",
    "units",
    "language",
    "room_area",
    "next_id",
    "types",
    "materials",
    "images",
    "clouds",
    "cads",
    "families",
    "parameters",
    "view_filters",
    "view_templates",
    "phases",
    "phase_filters",
    "phase_overrides",
    "option_sets",
    "line_weights",
    "standard",
    "object_styles",
    "line_patterns",
    "line_styles",
    "fill_patterns",
    "region_types",
    "text_types",
    "dimension_types",
    "detail_groups",
    "reinforcement",
    "voltages",
    "distribution_systems",
    "wire_types",
    "links",
    "elements",
    "library",
];
//! A session: the project, its file, and its undo history; commands run here.

use crate::json::Value;
use crate::project::Project;

pub struct Step {
    pub before: Project,
    pub after: Project,
    pub label: String,
}

pub struct Session {
    pub project: Project,
    pub path: Option<String>,
    pub undo: Vec<Step>,
    pub redo: Vec<Step>,
    pub read_only: bool,
    /// The phase and design option this session makes elements in.
    pub now_phase: Option<String>,
    pub now_option: Option<String>,
}

pub const MAX_UNDO: usize = 200;

impl Session {
    pub fn new() -> Session {
        Session {
            project: Project::new("en"),
            path: None,
            undo: Vec::new(),
            redo: Vec::new(),
            read_only: false,
            now_phase: None,
            now_option: None,
        }
    }

    /// Runs a command by id (or alias, any case) with its parameters.
    pub fn execute(&mut self, id: &str, params: &Value) -> Result<Value, String> {
        let Some((cid, label)) = crate::commands::resolve(id) else {
            return Err(format!("unknown command `{}`; list_commands shows them", id));
        };
        let before = self.project.clone();
        // the phase and option this session makes elements in go back with a refused command
        let now_before = (self.now_phase.clone(), self.now_option.clone());
        let res = crate::commands::run(self, &cid, params);
        match res {
            Ok(out) => {
                if crate::commands::changes_model(&cid) && !crate::commands::is_history_cmd(&cid) {
                    // a scan nothing places any more goes with the command that left it so
                    crate::cloud::drop_unplaced(&mut self.project);
                    if let Err(e) = crate::check::check(&self.project) {
                        self.project = before;
                        (self.now_phase, self.now_option) = now_before;
                        return Err(e);
                    }
                    if self.project.to_value() != before.to_value() || crate::commands::always_step(&cid) {
                        self.undo.push(Step { before, after: self.project.clone(), label: label.clone() });
                        if self.undo.len() > MAX_UNDO {
                            self.undo.remove(0);
                        }
                        self.redo.clear();
                    }
                }
                Ok(out)
            }
            Err(e) => {
                self.project = before;
                (self.now_phase, self.now_option) = now_before;
                Err(e)
            }
        }
    }

    pub fn history(&self) -> Vec<String> {
        self.undo.iter().map(|s| s.label.clone()).collect()
    }
}
//! The model's rules, checked after every command that changes it.

use crate::project::Project;

pub fn check(pr: &Project) -> Result<(), String> {
    core_check(pr)?;
    crate::cloud::check(pr)?;
    crate::media::check(pr)?;
    crate::styles::check(pr)?;
    crate::arch::check(pr)?;
    crate::structure::check(pr)?;
    crate::views::check(pr)?;
    crate::edit::check(pr)?;
    crate::readers::check(pr)?;
    Ok(())
}

fn core_check(pr: &Project) -> Result<(), String> {
    let mut level_names: Vec<String> = Vec::new();
    let mut grid_names: Vec<String> = Vec::new();
    for (id, e) in &pr.elements {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        match cat {
            "level" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if level_names.contains(&name) {
                    return Err(format!("level {}: another level is already named `{}`", id, name));
                }
                level_names.push(name);
                if let Some(ext) = e.get("extent").and_then(|x| x.as_arr()) {
                    let a = ext.first().and_then(crate::commands::params::point_of);
                    let b = ext.get(1).and_then(crate::commands::params::point_of);
                    if let (Some(a), Some(b)) = (a, b) {
                        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
                            return Err(format!(
                                "level {}: its extent runs from its south-west corner to its north-east one",
                                id
                            ));
                        }
                    }
                }
            }
            "grid" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if grid_names.contains(&name) {
                    return Err(format!("grid {}: another grid is already named `{}`", id, name));
                }
                grid_names.push(name);
                let a = e.get("start").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let b = e.get("end").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
                if len <= 1.0 {
                    return Err(format!("grid {}: too short ({} mm)", id, len));
                }
            }
            _ => {}
        }
    }
    Ok(())
}

//! The commands: their registry, dispatch, and the project-level ones.

pub mod basic;
pub mod params;

use crate::json::Value;
use crate::session::Session;
use std::sync::OnceLock;

pub struct CmdInfo {
    pub id: String,
    pub label: String,
    pub aliases: Vec<String>,
}

fn registry() -> &'static Vec<CmdInfo> {
    static REG: OnceLock<Vec<CmdInfo>> = OnceLock::new();
    REG.get_or_init(|| {
        let v = crate::json::parse(crate::catalog::CATALOG).unwrap();
        v.as_arr()
            .unwrap()
            .iter()
            .map(|c| CmdInfo {
                id: c.get("id").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                label: c.get("label").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                aliases: c
                    .get("aliases")
                    .and_then(|x| x.as_arr())
                    .map(|a| a.iter().filter_map(|s| s.as_str().map(|s| s.to_string())).collect())
                    .unwrap_or_default(),
            })
            .collect()
    })
}

/// A command's id and label, from its id or one of its aliases, in any case.
pub fn resolve(id: &str) -> Option<(String, String)> {
    let reg = registry();
    let low = id.to_lowercase();
    if let Some(c) = reg.iter().find(|c| c.id.to_lowercase() == low) {
        return Some((c.id.clone(), c.label.clone()));
    }
    if let Some(c) = reg.iter().find(|c| c.aliases.iter().any(|a| a.to_lowercase() == low)) {
        return Some((c.id.clone(), c.label.clone()));
    }
    None
}

pub fn label_of(cid: &str) -> String {
    registry().iter().find(|c| c.id == cid).map(|c| c.label.clone()).unwrap_or_default()
}

/// Commands that only read the model (no undo step, no check).
pub fn changes_model(cid: &str) -> bool {
    !matches!(
        cid,
        "inspect"
            | "elements"
            | "render"
            | "measure"
            | "library"
            | "select_by_id"
            | "ids_of"
            | "filter_selection"
            | "sketch"
            | "save"
            | "autosave"
            | "circuit"
            | "conduit_fill"
            | "drain_size"
            | "vent_size"
            | "hydrant_size"
            | "load_points"
            | "water_size"
            | "storm_size"
            | "export_fill_patterns"
            | "cad_query"
    )
}

/// Undo and redo move the history themselves; opening a project starts a new one.
pub fn is_history_cmd(cid: &str) -> bool {
    matches!(cid, "undo" | "redo" | "new" | "open" | "recover" | "highrise")
}

pub fn always_step(cid: &str) -> bool {
    // some commands make an undo step even when the model is unchanged; each module owns its own
    crate::media::always_step(cid) || crate::styles::step_anyway(cid)
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> Result<Value, String> {
    if s.read_only && changes_model(cid) && !matches!(cid, "save") {
        return Err(format!("{}: this project is open read-only, so it can't be changed", cid));
    }
    if let Some(r) = crate::cloud::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::media::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::styles::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::arch::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::structure::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::views::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::edit::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::readers::dispatch(s, cid, p) {
        return r;
    }
    basic::run(s, cid, p)
}

pub fn io_err(e: &std::io::Error) -> String {
    e.to_string()
}

pub fn open_path(s: &mut Session, path: &str) -> Result<Value, String> {
    basic::open_path(s, path)
}

pub fn info(path: &str) -> Result<Value, String> {
    basic::info(path)
}

pub fn build_sample(s: &mut Session) -> Result<(), String> {
    basic::build_sample(s)
}

pub fn build_highrise(s: &mut Session, storeys: u64) -> Result<Value, String> {
    basic::build_highrise(s, storeys)
}

pub fn mcp_main(args: &[String]) {
    crate::mcp::main(args)
}
//! Reading a command's parameters, with the errors the commands give.

use crate::json::Value;

pub type R<T> = Result<T, String>;

pub fn get<'a>(p: &'a Value, key: &str) -> Option<&'a Value> {
    match p.get(key) {
        Some(Value::Null) | None => None,
        Some(v) => Some(v),
    }
}

pub fn has(p: &Value, key: &str) -> bool {
    get(p, key).is_some()
}

/// Present in the object, even as null.
pub fn given(p: &Value, key: &str) -> bool {
    p.get(key).is_some()
}

pub fn num_of(v: &Value) -> Option<f64> {
    match v {
        Value::Num(n) => Some(n.as_f64()),
        _ => None,
    }
}

/// The largest length a command takes, in mm (1000 km).
pub const MAX_MM: f64 = 1e9;

/// A length in mm, within the model's reach.
pub fn mm_of(v: &Value) -> Option<f64> {
    let x = num_of(v)?;
    if x.is_finite() && x.abs() <= MAX_MM {
        Some(x)
    } else {
        None
    }
}

pub fn req_num(p: &Value, cmd: &str, key: &str) -> R<f64> {
    match get(p, key) {
        None => Err(format!("{}: `{}` in mm is required", cmd, key)),
        Some(v) => mm_of(v).ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_num(p: &Value, cmd: &str, key: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => mm_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A number in some unit other than mm (degrees, percent…).
pub fn opt_num_unit(p: &Value, cmd: &str, key: &str, unit: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => num_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number{}, got {}", cmd, key, unit, v.to_compact())),
    }
}

pub fn opt_text(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Str(s)) if s.chars().count() <= 256 => Ok(Some(s.clone())),
        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_bool(p: &Value, cmd: &str, key: &str) -> R<Option<bool>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Bool(b)) => Ok(Some(*b)),
        Some(v) => Err(format!("{}: `{}` must be true or false, got {}", cmd, key, v.to_compact())),
    }
}

pub fn point_of(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?])
}

pub fn point3_of(v: &Value) -> Option<[f64; 3]> {
    let a = v.as_arr()?;
    if a.len() != 3 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?, mm_of(&a[2])?])
}

pub fn req_point(p: &Value, cmd: &str, key: &str) -> R<[f64; 2]> {
    match get(p, key) {
        None => Err(format!("{}: `{}` [x, y] is required", cmd, key)),
        Some(v) => point_of(v).ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_point(p: &Value, cmd: &str, key: &str) -> R<Option<[f64; 2]>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => point_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A list of points; anything but a list of points reads as missing.
pub fn points_of(v: &Value) -> Option<Vec<[f64; 2]>> {
    let a = v.as_arr()?;
    a.iter().map(point_of).collect()
}

pub fn req_points(p: &Value, cmd: &str, key: &str) -> R<Vec<[f64; 2]>> {
    match get(p, key).and_then(points_of) {
        None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        Some(v) => Ok(v),
    }
}

pub fn opt_points(p: &Value, cmd: &str, key: &str) -> R<Option<Vec<[f64; 2]>>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => match points_of(v) {
            Some(pts) => Ok(Some(pts)),
            None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        },
    }
}

/// An element id: a number, or a GUID or an id in a string.
pub fn id_of(v: &Value) -> Option<u64> {
    match v {
        Value::Num(n) => {
            let f = n.as_f64();
            if f >= 0.0 && f.fract() == 0.0 {
                Some(f as u64)
            } else {
                None
            }
        }
        Value::Str(s) => s.trim().parse::<u64>().ok(),
        _ => None,
    }
}
//! Common lookups on the model: levels, elements by id or GUID.

use crate::json::Value;
use crate::project::Project;

/// Levels from the lowest up (ties by id).
pub fn levels(pr: &Project) -> Vec<u64> {
    crate::commands::basic::level_ids_sorted(pr)
}

pub fn elev(pr: &Project, level: u64) -> f64 {
    pr.el(level).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

pub fn name(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| e.get("name")).and_then(|x| x.as_str()).unwrap_or("").to_string()
}

/// The lowest level, where commands go without one.
pub fn default_level(pr: &Project) -> Option<u64> {
    levels(pr).first().copied()
}

/// The next level up from one, if any.
pub fn level_above(pr: &Project, level: u64) -> Option<u64> {
    let ls = levels(pr);
    let i = ls.iter().position(|l| *l == level)?;
    ls.get(i + 1).copied()
}

/// An element by its id (a number or a string of one) or its GUID.
pub fn find(pr: &Project, v: &Value) -> Option<u64> {
    match v {
        Value::Num(_) => {
            let id = crate::commands::params::id_of(v)?;
            if pr.elements.contains_key(&id) {
                Some(id)
            } else {
                None
            }
        }
        Value::Str(s) => {
            let t = s.trim();
            if let Ok(id) = t.parse::<u64>() {
                return if pr.elements.contains_key(&id) { Some(id) } else { None };
            }
            let g = normalize_guid(t)?;
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A GUID as the model keeps it (lowercase, hyphenated), from one with or without braces and dashes.
pub fn normalize_guid(s: &str) -> Option<String> {
    let t = s.trim().trim_start_matches('{').trim_end_matches('}');
    let hex: String = t.chars().filter(|c| *c != '-').collect();
    if hex.len() != 32 || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let h = hex.to_lowercase();
    Some(format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32]))
}

/// A level (or a plan view, whose level it is) given by name, id or GUID.
pub fn resolve_level(pr: &Project, cmd: &str, key: &str, v: &Value) -> Result<u64, String> {
    let not = || format!("{}: `{}`: {} is not a level or a plan view", cmd, key, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = find(pr, v).ok_or_else(not)?;
            level_of_view(pr, id).ok_or_else(not)
        }
        Value::Str(s) => {
            if let Some(id) = find(pr, v) {
                return level_of_view(pr, id).ok_or_else(not);
            }
            if s.trim().parse::<u64>().is_ok() || normalize_guid(s).is_some() {
                return Err(not());
            }
            for id in levels(pr) {
                if name(pr, id) == *s {
                    return Ok(id);
                }
            }
            for id in pr.ids_of("planview") {
                if name(pr, id) == *s {
                    if let Some(l) = level_of_view(pr, id) {
                        return Ok(l);
                    }
                }
            }
            let names: Vec<String> = levels(pr).iter().map(|l| name(pr, *l)).collect();
            Err(format!(
                "{}: no level or plan view named `{}` (the levels are: {})",
                cmd,
                s,
                names.join(", ")
            ))
        }
        _ => Err(not()),
    }
}

/// The level of a level, or of a plan view.
pub fn level_of_view(pr: &Project, id: u64) -> Option<u64> {
    match pr.category(id)? {
        "level" => Some(id),
        "planview" => {
            let g = pr.el(id)?.get("level")?.as_str()?.to_string();
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A level from the params' `key`, else the lowest.
pub fn level_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> Result<u64, String> {
    match crate::commands::params::get(p, key) {
        Some(v) => resolve_level(pr, cmd, key, v),
        None => default_level(pr).ok_or_else(|| format!("{}: the project has no level", cmd)),
    }
}

//! Projects, history, levels and grids.

use super::params::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "new" => cmd_new(s, p),
        "open" => {
            let path = match opt_text(p, "open", "path")? {
                Some(x) => x,
                None => return Err("open: `path` is required".into()),
            };
            // the script's `open` reads a project file whatever its extension: a Revit file is
            // imported only by `run x.rvt`, `convert` and the MCP server's `open`
            open_project_file(s, &path).map_err(|e| format!("open: {}", e))
        }
        "save" => cmd_save(s, p),
        "undo" => cmd_undo(s, p, true),
        "redo" => cmd_undo(s, p, false),
        "level" => cmd_level(s, p),
        "grid" => cmd_grid(s, p),
        "delete" => cmd_delete(s, p),
        "inspect" => Ok(crate::inspect::inspect(s)),
        "elements" => crate::inspect::elements(s, p),
        _ => Err(format!("{}: not supported here", cid)),
    }
}

// ---------------------------------------------------------------- projects

fn cmd_new(s: &mut Session, p: &Value) -> R<Value> {
    let name = opt_text(p, "new", "name")?;
    let lang = opt_text(p, "new", "language")?.unwrap_or_else(|| "en".into()).to_lowercase();
    if !crate::project::LANGS.contains(&lang.as_str()) {
        return Err(format!("new: `{}` is no language here; use en, pt, es or sv", lang));
    }
    let mut proj = Project::new(&lang);
    if let Some(n) = name {
        proj.doc.insert("name", Value::Str(n));
    }
    s.project = proj;
    s.now_phase = None;
    s.now_option = None;
    s.path = None;
    s.undo.clear();
    s.redo.clear();
    Ok(jobj! {"language" => lang, "name" => s.project.name()})
}

/// Opens a project, or imports a file by its extension.
pub fn open_path(s: &mut Session, path: &str) -> Result<Value, String> {
    let low = path.to_lowercase();
    if crate::rvt::is_revit_path(path) {
        return crate::rvt::import(s, path);
    }
    let _ = low;
    open_project_file(s, path)
}

/// Opens a project file (or an IFC file), whatever the extension says otherwise.
pub fn open_project_file(s: &mut Session, path: &str) -> Result<Value, String> {
    let low = path.to_lowercase();
    if low.ends_with(".ifc") {
        return crate::ifc::import::import(s, path);
    }
    let text = std::fs::read_to_string(path).map_err(|e| format!("{}: {}", path, e))?;
    let v = crate::json::parse(&text).map_err(|e| format!("{} is not a BIMCraft project: {}", path, e))?;
    let proj = crate::load::load(v).map_err(|e| format!("{} is not a BIMCraft project: {}", path, e))?;
    // what the file's point clouds place must be there (the original checks its model on opening)
    crate::cloud::check(&proj).map_err(|e| format!("{}: {}", path, e))?;
    s.project = proj;
    s.now_phase = None;
    s.now_option = None;
    s.path = Some(path.to_string());
    s.undo.clear();
    s.redo.clear();
    Ok(jobj! {"name" => s.project.name(), "path" => path})
}

fn cmd_save(s: &mut Session, p: &Value) -> R<Value> {
    let path = match opt_text(p, "save", "path")? {
        Some(x) => x,
        None => match &s.path {
            Some(x) => x.clone(),
            None => return Err("save: `path` is required: this project hasn't been saved yet".into()),
        },
    };
    let low = path.to_lowercase();
    if low.ends_with(".ifc") {
        let text = crate::ifc::export::export(&s.project, &path);
        std::fs::write(&path, text).map_err(|e| format!("save: {}: {}", path, e))?;
        return Ok(jobj! {"format" => "IFC4", "path" => path});
    }
    let text = s.project.to_file_string();
    write_atomic(&path, text.as_bytes()).map_err(|e| format!("save: {}: {}", path, e))?;
    s.path = Some(path.clone());
    Ok(jobj! {"format" => "bimcraft", "path" => path})
}

/// Writes a file as tempfile and persist do: a hidden file beside it, renamed over it.
pub fn write_atomic(path: &str, bytes: &[u8]) -> Result<(), String> {
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;
    let p = std::path::Path::new(path);
    let parent = match p.parent() {
        Some(d) if !d.as_os_str().is_empty() => d.to_path_buf(),
        _ => std::path::PathBuf::from(""),
    };
    let dir = if parent.is_absolute() {
        parent
    } else {
        std::env::current_dir().map_err(|e| e.to_string())?.join(parent)
    };
    let tmp = dir.join(format!(".tmp{}", crate::rand::alnum(6)));
    let mut f = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(&tmp)
        .map_err(|e| format!("{} at path {:?}", e, tmp.to_string_lossy()))?;
    f.write_all(bytes).map_err(|e| format!("{} at path {:?}", e, tmp.to_string_lossy()))?;
    drop(f);
    std::fs::rename(&tmp, p).map_err(|e| {
        let _ = std::fs::remove_file(&tmp);
        format!("{} at path {:?}", e, tmp.to_string_lossy())
    })?;
    Ok(())
}

fn cmd_undo(s: &mut Session, p: &Value, undo: bool) -> R<Value> {
    let cmd = if undo { "undo" } else { "redo" };
    let avail = if undo { s.undo.len() } else { s.redo.len() };
    if avail == 0 {
        return Err(if undo { "nothing to undo".into() } else { "nothing to redo".into() });
    }
    let count = match get(p, "count") {
        None => 1,
        Some(v) => match v.as_f64() {
            Some(c) if c >= 1.0 && c <= avail as f64 && c.fract() == 0.0 => c as usize,
            _ => {
                return Err(format!(
                    "`count` must be from 1 to {}, the steps there are to {}",
                    avail, cmd
                ))
            }
        },
    };
    let mut label = String::new();
    for _ in 0..count {
        if undo {
            let step = s.undo.pop().unwrap();
            s.project = step.before.clone();
            label = step.label.clone();
            s.redo.push(step);
        } else {
            let step = s.redo.pop().unwrap();
            s.project = step.after.clone();
            label = step.label.clone();
            s.undo.push(step);
        }
    }
    let mut m = Map::new();
    m.insert("count", Value::u(count as u64));
    m.insert(if undo { "undone" } else { "redone" }, Value::Str(label));
    Ok(Value::Obj(m))
}

// ---------------------------------------------------------------- levels and grids

pub fn level_ids_sorted(pr: &Project) -> Vec<u64> {
    let mut ids = pr.ids_of("level");
    ids.sort_by(|a, b| {
        let ea = pr.el(*a).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0);
        let eb = pr.el(*b).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0);
        ea.partial_cmp(&eb).unwrap_or(std::cmp::Ordering::Equal).then(a.cmp(b))
    });
    ids
}

pub fn level_word(lang: &str) -> &'static str {
    match lang {
        "pt" => "Nível",
        "es" => "Nivel",
        "sv" => "Nivå",
        "cs" => "Podlaží",
        "fr" => "Niveau",
        "nl" => "Niveau",
        "de" => "Ebene",
        "it" => "Livello",
        _ => "Level",
    }
}

fn cmd_level(s: &mut Session, p: &Value) -> R<Value> {
    let elevation = req_num(p, "level", "elevation")?;
    let name = opt_text(p, "level", "name")?;
    let extent = match get(p, "extent") {
        None => None,
        Some(v) => {
            let pts = points_of(v).ok_or_else(|| "level: `extent` [[x, y], …] is required".to_string())?;
            if pts.len() != 2 {
                return Err("level: `extent` is two corners, [[x, y], [x, y]]: south-west, then north-east".into());
            }
            Some(pts)
        }
    };
    let pr = &mut s.project;
    let name = match name {
        Some(n) => n,
        None => {
            let word = level_word(&pr.language());
            let names: Vec<String> = pr
                .ids_of("level")
                .iter()
                .filter_map(|id| pr.el(*id).and_then(|e| e.get("name")).and_then(|n| n.as_str()).map(|s| s.to_string()))
                .collect();
            let mut n = names.len() + 1;
            loop {
                let cand = format!("{} {}", word, n);
                if !names.contains(&cand) {
                    break cand;
                }
                n += 1;
            }
        }
    };
    let id = pr.alloc_id();
    let mut e = jobj! {
        "guid" => crate::rand::guid(),
        "category" => "level",
        "name" => name.clone(),
        "elevation" => elevation,
        "view_range" => jobj!{"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0},
    };
    if let Some(x) = extent {
        e.set("extent", Value::Arr(vec![x[0].into(), x[1].into()]));
    }
    pr.elements.insert(id, e);
    Ok(jobj! {"id" => id, "name" => name})
}

fn is_number_name(s: &str) -> Option<u64> {
    if !s.is_empty() && s.chars().all(|c| c.is_ascii_digit()) {
        s.parse().ok()
    } else {
        None
    }
}

fn cmd_grid(s: &mut Session, p: &Value) -> R<Value> {
    let start = req_point(p, "grid", "start")?;
    let end = req_point(p, "grid", "end")?;
    let name = opt_text(p, "grid", "name")?;
    let pr = &mut s.project;
    let grids = pr.ids_of("grid");
    let names: Vec<String> = grids
        .iter()
        .filter_map(|id| pr.el(*id).and_then(|e| e.get("name")).and_then(|n| n.as_str()).map(|s| s.to_string()))
        .collect();
    let name = match name {
        Some(n) => n,
        None => {
            let last = names.last().cloned().unwrap_or_default();
            let letter = {
                let mut c = last.chars();
                match (c.next(), c.next()) {
                    (Some(ch), None) if ch.is_ascii_uppercase() && ch != 'Z' => Some(ch),
                    _ => None,
                }
            };
            if let Some(ch) = letter {
                let mut ch = (ch as u8 + 1) as char;
                loop {
                    let cand = ch.to_string();
                    if !names.contains(&cand) || ch == 'Z' {
                        break cand;
                    }
                    ch = (ch as u8 + 1) as char;
                }
            } else {
                let mut n = names.iter().filter_map(|n| is_number_name(n)).max().unwrap_or(0) + 1;
                loop {
                    let cand = n.to_string();
                    if !names.contains(&cand) {
                        break cand;
                    }
                    n += 1;
                }
            }
        }
    };
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "grid",
            "name" => name.clone(),
            "start" => start,
            "end" => end,
        },
    );
    Ok(jobj! {"id" => id, "name" => name})
}

// ---------------------------------------------------------------- delete

fn cmd_delete(s: &mut Session, p: &Value) -> R<Value> {
    let ids: Vec<u64> = match get(p, "ids").and_then(|v| v.as_arr()) {
        Some(a) => a.iter().filter_map(id_of).collect(),
        None => return Err("delete: `ids` [id, …] is required".into()),
    };
    let pr = &mut s.project;
    let mut deleted = Vec::new();
    for id in ids {
        if pr.elements.remove(&id).is_some() {
            deleted.push(id);
        }
    }
    Ok(jobj! {"deleted" => deleted})
}

