fn usage_exit(prefix: Option<String>) -> ! {
    if let Some(p) = prefix {
        eprint!("{}\n\n", p);
    }
    eprint!("{}", catalog::USAGE);
    exit(1);
}

enum Action {
    Open(String),
    Sample,
    Highrise,
    Cmd(String),
    Script(String),
    Save(String),
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() {
        usage_exit(None);
    }
    match args[0].as_str() {
        "--version" | "-V" if args.len() == 1 => {
            println!("bimcraft-cli {}", VERSION);
        }
        "commands" if args.len() == 1 => {
            let v = json::parse(catalog::CATALOG).unwrap();
            println!("{}", v.to_pretty());
        }
        "info" if args.len() == 2 => cmd_info(&args[1]),
        "convert" if args.len() == 3 => cmd_convert(&args[1], &args[2]),
        "run" => cmd_run(&args[1..]),
        "mcp" => commands::mcp_main(&args[1..]),
        _ => usage_exit(None),
    }
}

fn cmd_run(args: &[String]) {
    let mut actions = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--sample" => actions.push(Action::Sample),
            "--highrise" => actions.push(Action::Highrise),
            "--cmd" | "--script" | "--save" => {
                if i + 1 >= args.len() {
                    usage_exit(Some(format!("{} needs a value", a)));
                }
                let v = args[i + 1].clone();
                i += 1;
                actions.push(match a.as_str() {
                    "--cmd" => Action::Cmd(v),
                    "--script" => Action::Script(v),
                    _ => Action::Save(v),
                });
            }
            _ if a.starts_with("--") => usage_exit(Some(format!("unknown option `{}`", a))),
            _ => actions.push(Action::Open(a.clone())),
        }
        i += 1;
    }
    let mut s = session::Session::new();
    for act in actions {
        match act {
            Action::Open(path) => match commands::open_path(&mut s, &path) {
                Ok(v) => println!("{}", v.sorted().to_compact()),
                Err(e) => {
                    // a Revit import's error is a whole message, the path first
                    if rvt::is_revit_path(&path) {
                        eprintln!("{}", e);
                    } else {
                        eprintln!("open: {}", e);
                    }
                    exit(1);
                }
            },
            Action::Sample => {
                if let Err(e) = commands::build_sample(&mut s) {
                    eprintln!("{}", e);
                    exit(1);
                }
            }
            Action::Highrise => match commands::build_highrise(&mut s, 20) {
                Ok(v) => println!("{}", v.sorted().to_compact()),
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            },
            Action::Cmd(text) => run_script_text(&mut s, &text),
            Action::Script(path) => match std::fs::read(&path) {
                Ok(bytes) => {
                    let text = String::from_utf8_lossy(&bytes).to_string();
                    run_script_text(&mut s, &text)
                }
                Err(e) => {
                    eprintln!("{}: {}", path, commands::io_err(&e));
                    exit(1);
                }
            },
            Action::Save(path) => {
                let p = json::Value::Obj({
                    let mut m = json::Map::new();
                    m.insert("path", json::Value::s(&path));
                    m
                });
                match s.execute("save", &p) {
                    Ok(v) => println!("{}", v.sorted().to_compact()),
                    Err(e) => {
                        eprintln!("save: {}", e);
                        exit(1);
                    }
                }
            }
        }
    }
}

fn run_script_text(s: &mut session::Session, text: &str) {
    let lines = match script::parse(text) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };
    // a script's replies are printed once all of it has gone through
    let mut out = String::new();
    for l in lines {
        match s.execute(&l.id, &l.params) {
            Ok(v) => {
                out.push_str(&v.sorted().to_compact());
                out.push('\n');
            }
            Err(e) => {
                eprintln!("line {} ({}): {}", l.line, l.id, e);
                exit(1);
            }
        }
    }
    print!("{}", out);
}

fn cmd_info(path: &str) {
    match commands::info(path) {
        Ok(v) => println!("{}", v.sorted().to_pretty()),
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    }
}

fn cmd_convert(input: &str, output: &str) {
    let mut s = session::Session::new();
    match commands::open_path(&mut s, input) {
        Ok(_) => {}
        Err(e) => {
            // a Revit import's error is a whole message, the path first
            if rvt::is_revit_path(input) {
                eprintln!("{}", e);
            } else {
                eprintln!("open: {}", e);
            }
            exit(1);
        }
    }
    let mut m = json::Map::new();
    m.insert("path", json::Value::s(output));
    match s.execute("save", &json::Value::Obj(m)) {
        Ok(v) => println!("{}", v.sorted().to_compact()),
        Err(e) => {
            eprintln!("save: {}", e);
            exit(1);
        }
    }
}

//! A JSON value with insertion-ordered objects, a parser whose errors read as
//! serde_json's do, and writers (compact, pretty, key-sorted) that format numbers
//! the way serde_json does (integers as integers, floats in shortest form).

use std::fmt::Write as _;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Num(Num),
    Str(String),
    Arr(Vec<Value>),
    Obj(Map),
}

impl Default for Value {
    fn default() -> Value {
        Value::Null
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Num {
    U(u64),
    I(i64),
    F(f64),
}

impl PartialEq for Num {
    fn eq(&self, other: &Num) -> bool {
        match (self, other) {
            (Num::U(a), Num::U(b)) => a == b,
            (Num::I(a), Num::I(b)) => a == b,
            (Num::F(a), Num::F(b)) => a == b,
            _ => false,
        }
    }
}

impl Num {
    pub fn as_f64(&self) -> f64 {
        match *self {
            Num::U(u) => u as f64,
            Num::I(i) => i as f64,
            Num::F(f) => f,
        }
    }
}

/// An object: keys in insertion order.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Map {
    pub items: Vec<(String, Value)>,
}

impl Map {
    pub fn new() -> Map {
        Map { items: Vec::new() }
    }
    pub fn get(&self, k: &str) -> Option<&Value> {
        self.items.iter().find(|(kk, _)| kk == k).map(|(_, v)| v)
    }
    pub fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
        self.items.iter_mut().find(|(kk, _)| kk == k).map(|(_, v)| v)
    }
    pub fn contains(&self, k: &str) -> bool {
        self.items.iter().any(|(kk, _)| kk == k)
    }
    /// Sets a key, keeping its place if it is there, else appending it.
    pub fn insert(&mut self, k: &str, v: Value) {
        if let Some(slot) = self.get_mut(k) {
            *slot = v;
        } else {
            self.items.push((k.to_string(), v));
        }
    }
    /// Sets a key in sorted (byte) order, as a BTreeMap would hold it.
    pub fn insert_sorted(&mut self, k: &str, v: Value) {
        match self.items.binary_search_by(|(kk, _)| kk.as_str().cmp(k)) {
            Ok(i) => self.items[i].1 = v,
            Err(i) => self.items.insert(i, (k.to_string(), v)),
        }
    }
    pub fn remove(&mut self, k: &str) -> Option<Value> {
        let i = self.items.iter().position(|(kk, _)| kk == k)?;
        Some(self.items.remove(i).1)
    }
    pub fn len(&self) -> usize {
        self.items.len()
    }
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
    pub fn keys(&self) -> impl Iterator<Item = &String> {
        self.items.iter().map(|(k, _)| k)
    }
    pub fn iter(&self) -> impl Iterator<Item = (&String, &Value)> {
        self.items.iter().map(|(k, v)| (k, v))
    }
    pub fn sort(&mut self) {
        self.items.sort_by(|a, b| a.0.cmp(&b.0));
    }
}

impl Value {
    pub fn obj() -> Value {
        Value::Obj(Map::new())
    }
    pub fn f(x: f64) -> Value {
        Value::Num(Num::F(x))
    }
    pub fn u(x: u64) -> Value {
        Value::Num(Num::U(x))
    }
    pub fn i(x: i64) -> Value {
        if x >= 0 {
            Value::Num(Num::U(x as u64))
        } else {
            Value::Num(Num::I(x))
        }
    }
    pub fn s(x: &str) -> Value {
        Value::Str(x.to_string())
    }
    pub fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }
    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Value::Num(n) => Some(n.as_f64()),
            _ => None,
        }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match self {
            Value::Num(Num::U(u)) if *u <= i64::MAX as u64 => Some(*u as i64),
            Value::Num(Num::I(i)) => Some(*i),
            _ => None,
        }
    }
    pub fn as_u64(&self) -> Option<u64> {
        match self {
            Value::Num(Num::U(u)) => Some(*u),
            _ => None,
        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::Str(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            _ => None,
        }
    }
    pub fn as_arr(&self) -> Option<&Vec<Value>> {
        match self {
            Value::Arr(a) => Some(a),
            _ => None,
        }
    }
    pub fn as_arr_mut(&mut self) -> Option<&mut Vec<Value>> {
        match self {
            Value::Arr(a) => Some(a),
            _ => None,
        }
    }
    pub fn as_obj(&self) -> Option<&Map> {
        match self {
            Value::Obj(m) => Some(m),
            _ => None,
        }
    }
    pub fn as_obj_mut(&mut self) -> Option<&mut Map> {
        match self {
            Value::Obj(m) => Some(m),
            _ => None,
        }
    }
    pub fn get(&self, k: &str) -> Option<&Value> {
        match self {
            Value::Obj(m) => m.get(k),
            _ => None,
        }
    }
    pub fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
        match self {
            Value::Obj(m) => m.get_mut(k),
            _ => None,
        }
    }
    /// Sets a key of an object (appending a new key at the end).
    pub fn set(&mut self, k: &str, v: Value) {
        if let Value::Obj(m) = self {
            m.insert(k, v);
        }
    }
    pub fn remove(&mut self, k: &str) -> Option<Value> {
        match self {
            Value::Obj(m) => m.remove(k),
            _ => None,
        }
    }
    /// The kind of value, as serde names it in "invalid type" errors.
    pub fn kind_name(&self) -> String {
        match self {
            Value::Null => "null".into(),
            Value::Bool(b) => format!("boolean `{}`", b),
            Value::Num(Num::U(u)) => format!("integer `{}`", u),
            Value::Num(Num::I(i)) => format!("integer `{}`", i),
            Value::Num(Num::F(f)) => format!("floating point `{}`", fmt_f64_display(*f)),
            Value::Str(s) => format!("string {:?}", s),
            Value::Arr(_) => "sequence".into(),
            Value::Obj(_) => "map".into(),
        }
    }
    /// Recursively sorts every object's keys, as serde_json::Value holds them.
    pub fn sorted(mut self) -> Value {
        self.sort_keys();
        self
    }
    pub fn sort_keys(&mut self) {
        match self {
            Value::Arr(a) => a.iter_mut().for_each(|v| v.sort_keys()),
            Value::Obj(m) => {
                m.items.iter_mut().for_each(|(_, v)| v.sort_keys());
                // stable: a duplicate key keeps the last value as a BTreeMap would
                m.items.sort_by(|a, b| a.0.cmp(&b.0));
                let mut out: Vec<(String, Value)> = Vec::with_capacity(m.items.len());
                for (k, v) in m.items.drain(..) {
                    if let Some(last) = out.last_mut() {
                        if last.0 == k {
                            last.1 = v;
                            continue;
                        }
                    }
                    out.push((k, v));
                }
                m.items = out;
            }
            _ => {}
        }
    }
    pub fn to_compact(&self) -> String {
        let mut s = String::new();
        write_compact(self, &mut s);
        s
    }
    pub fn to_pretty(&self) -> String {
        let mut s = String::new();
        write_pretty(self, &mut s, 0);
        s
    }
}

