        "link" | "reload" => link::run(s, cid, p),
        "purge" => purge::run(s, p),
        "delete_type" | "rename_type" => types::run(s, cid, p),
        "autosave" | "recover" => autosave::run(s, cid, p),
        _ => return None,
    };
    Some(r)
}

/// Commands of this module that make an undo step even when the model is as it was.
