import sys, json; sys.path.insert(0, '/tmp/edit-agent')
from lib import *
F = sys.argv[1]
cmdt = sys.argv[2]
ids = [int(x) for x in sys.argv[3].split(',')] if len(sys.argv) > 3 else None
code, r, e, base = run([], src=F)
for k, v in els(base).items():
    if ids and k not in ids: continue
    if not ids and v['category'] in ('wall', 'level'): continue
    code, r, e, p = run([cmdt % k], src=F)
    print('==', k, v['category'], code, r, e)
    if p:
        A = base['elements']; B = p['elements']
        for kk in sorted(set(A) | set(B), key=int):
            if kk not in B: print('   -', kk, A[kk]['category'])
            elif kk not in A: print('   +', kk, json.dumps(B[kk])[:600])
            elif A[kk] != B[kk]:
                x, y = A[kk], B[kk]
                diffs = []
                for f in list(y.keys()) + [f for f in x if f not in y]:
                    if x.get(f) != y.get(f):
                        diffs.append('%s: %s -> %s' % (f, json.dumps(x.get(f))[:300], json.dumps(y.get(f))[:300]))
                if list(x.keys()) != [f for f in y.keys() if f in x]:
                    diffs.append('ORDER %s' % list(y.keys()))
                print('   ~', kk, y.get('category'), '; '.join(diffs))
        for kk in sorted(set(base) | set(p)):
            if kk not in ('elements', 'library', 'uid') and base.get(kk) != p.get(kk):
                print('   TOP', kk, json.dumps(p.get(kk))[:400])

