#!/usr/bin/env python3
"""cmpb.py cases.txt [-j N] [-q]: each case is a block: 'FILE path' (optional, repeatable), then command lines, separated by '---'.
Runs original and mine (run in.bimcraft --script s.txt --save out.bimcraft), compares normalised outputs.
Cases where the original fails with a model-check error (no `cmd:` prefix) are counted as CHECK when mine succeeds."""
import os, re, subprocess, sys, tempfile, shutil, difflib, json
from multiprocessing import Pool
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a76b15059404997b3/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m)+1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    return s
def run(exe, files, cmds, main_file):
    d = tempfile.mkdtemp(prefix='cmpb')
    for f in files: shutil.copy(f, d)
    open(os.path.join(d, 's.txt'), 'w').write('\n'.join(cmds) + '\n')
    args = [exe, 'run']
    if main_file: args.append(os.path.basename(main_file))
    args += ['--script', 's.txt', '--save', 'out.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=120)
    out = {'code': p.returncode, 'stdout': p.stdout.decode('utf-8', 'replace'), 'stderr': p.stderr.decode('utf-8', 'replace')}
    f = os.path.join(d, 'out.bimcraft')
    out['file'] = open(f).read() if os.path.exists(f) else None
    shutil.rmtree(d)
    return out
def one(c):
    files = []; cmds = []
    for l in c.splitlines():
        if l.startswith('FILE '): files.append(l[5:].strip())
        elif l.strip() and not l.startswith('#'): cmds.append(l)
    main_file = files[0] if files else None
    o = run(ORIG, files, cmds, main_file)
    m = run(MINE, files, cmds, main_file)
    diffs = []
    for k in ('code', 'stdout', 'stderr', 'file'):
        x = norm(str(o[k])); y = norm(str(m[k]))
        if x != y:
            diffs.append(k)
            dl = list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=1))[:24]
            diffs.append('\n'.join(l[:400] for l in dl))
    kind = 'SAME'
    if diffs:
        kind = 'DIFF'
        mm = re.match(r'line \d+ \((\w+)\): (.*)', o['stderr'].strip())
        if o['code'] != 0 and m['code'] == 0 and mm and not mm.group(2).startswith(mm.group(1) + ':'):
            kind = 'CHECK'
    return kind, cmds, diffs, o['stderr'].strip()
def main():
    text = open(sys.argv[1]).read()
    j = 8
    if '-j' in sys.argv: j = int(sys.argv[sys.argv.index('-j') + 1])
    quiet_check = '-q' in sys.argv
    cases = [c.strip() for c in text.split('\n---\n') if c.strip()]
    with Pool(j) as pool:
        res = pool.map(one, cases, chunksize=4)
    counts = {}
    for i, (kind, cmds, diffs, oerr) in enumerate(res):
        counts[kind] = counts.get(kind, 0) + 1
        if kind == 'DIFF' or (kind == 'CHECK' and not quiet_check):
            print('=== CASE %d %s: %s' % (i, kind, ' | '.join(cmds)[:300]))
            if kind == 'CHECK':
                print('   orig:', oerr[:300])
            else:
                for d in diffs: print(d)
    print(' '.join('%s %d' % kv for kv in sorted(counts.items())))
main()

