from fractions import Fraction as F
import math
def fma(a, b, c):
    return float(F(a) * F(b) + F(c))
def dot_f(a, b):
    # fused: a.x*b.x + a.y*b.y with the second product fused into the add (x*y + (z*w)) as LLVM would
    return fma(a[0], b[0], a[1] * b[1])
def dot_f2(a, b):
    return fma(a[1], b[1], a[0] * b[0])
if __name__ == '__main__':
    dx, dy = 3000.2000000000003, 4000.5
    for name, l2 in [('f1', fma(dx, dx, dy*dy)), ('f2', fma(dy, dy, dx*dx)), ('plain', dx*dx+dy*dy)]:
        L = math.sqrt(l2)
        print(name, repr(L), repr(L - 1234.5))
    a = (10.1, 20.2); b = (3010.3, 4020.7)
    d = (b[0]-a[0], b[1]-a[1])
    for p, exp in [((771.8, 1005.5), 1245.259490524894), ((1510.0, 2020.0), 2499.7799979004058), ((1510.2, 2019.4), 2499.419983342061)]:
        v = (p[0]-a[0], p[1]-a[1])
        for dn, df in [('f1', dot_f), ('f2', dot_f2), ('plain', lambda x, y: x[0]*y[0]+x[1]*y[1])]:
