1	//! Move, Copy, Rotate and Mirror: elements of every category, and the walls joined to them.
2	//!
3	//! The original works its geometry as glam's DVec2 does (a direction normalised by the reciprocal
4	//! of its length); a turned or mirrored point is rounded to 0.001 mm, and an angle is the direction
5	//! between a point and one 1000 mm along it, both taken through the transform, rounded to 1e-9
6	//! degree. A moved wall's end joined to walls it isn't moved with (an end within 1 mm of theirs, or
7	//! on one of them) goes where its new line crosses the first of them (by id), and their ends go
8	//! with it; a wall ending on a moved one goes to where its line crosses the moved one's. Doors and
9	//! windows of moved walls go with them, and those of walls that stretch stay where they stand.
10	
11	use super::common::*;
12	use crate::json::Value;
13	use crate::project::Project;
14	use crate::session::Session;
15	use std::collections::{BTreeMap, BTreeSet};
16	
17	pub type P = [f64; 2];
18	
19	// ---------------------------------------------------------------- vectors, as glam does them
20	
21	pub fn sub(a: P, b: P) -> P {
22	    [a[0] - b[0], a[1] - b[1]]
23	}
24	pub fn add(a: P, b: P) -> P {
25	    [a[0] + b[0], a[1] + b[1]]
26	}
27	pub fn mul(a: P, k: f64) -> P {
28	    [a[0] * k, a[1] * k]
29	}
30	pub fn dot(a: P, b: P) -> f64 {
31	    a[0] * b[0] + a[1] * b[1]
32	}
33	pub fn cross(a: P, b: P) -> f64 {
34	    a[0] * b[1] - a[1] * b[0]
35	}
36	pub fn length(a: P) -> f64 {
37	    dot(a, a).sqrt()
38	}
39	pub fn normalize(a: P) -> P {
40	    mul(a, 1.0 / length(a))
41	}
42	pub fn dist(a: P, b: P) -> f64 {
43	    length(sub(a, b))
44	}
45	
46	/// Rounds to 1e-9 (an angle in degrees, a unit vector's components).
47	pub fn r9(x: f64) -> f64 {
48	    let y = (x * 1e9).round() / 1e9;
49	    if y == 0.0 {
50	        0.0
51	    } else {
52	        y
53	    }
54	}
55	
56	pub fn r3p(p: P) -> P {
57	    [r3(p[0]), r3(p[1])]
58	}
59	
60	// ---------------------------------------------------------------- the transform
61	
62	#[derive(Clone, Copy, Debug)]
63	pub enum Xf {
64	    Move(P),
65	    Rotate { c: P, cos: f64, sin: f64 },
66	    Mirror { a: P, d: P },
67	}
68	
69	impl Xf {
70	    pub fn rotate(c: P, deg: f64) -> Xf {
71	        let (sin, cos) = deg.to_radians().sin_cos();
72	        Xf::Rotate { c, cos, sin }
73	    }
74	    pub fn mirror(a: P, b: P) -> Xf {
75	        Xf::Mirror { a, d: normalize(sub(b, a)) }
76	    }
77	    pub fn mirrors(&self) -> bool {
78	        matches!(self, Xf::Mirror { .. })
79	    }
80	    pub fn is_move(&self) -> bool {
81	        matches!(self, Xf::Move(_))
82	    }
83	    /// A point of the plan, where the transform takes it.
84	    pub fn pt(&self, p: P) -> P {
85	        match *self {
86	            Xf::Move(by) => add(p, by),
87	            Xf::Rotate { c, .. } => {
88	                let r = self.vec(sub(p, c));
89	                r3p(add(c, r))
90	            }
91	            Xf::Mirror { a, .. } => {
92	                let r = self.vec(sub(p, a));
93	                r3p(add(a, r))
94	            }
95	        }
96	    }
97	    /// A direction or a displacement, as the transform turns it (unrounded).
98	    pub fn vec(&self, v: P) -> P {
99	        match *self {
100	            Xf::Move(_) => v,
101	            Xf::Rotate { cos, sin, .. } => [v[0] * cos - v[1] * sin, v[1] * cos + v[0] * sin],
102	            Xf::Mirror { d, .. } => {
103	                let k = dot(v, d) * 2.0;
104	                sub(mul(d, k), v)
105	            }
106	        }
107	    }
108	    /// An angle (degrees) of something at `p`, after the transform: a move keeps it.
109	    pub fn ang(&self, p: P, deg: f64) -> f64 {
110	        if self.is_move() {
111	            return deg;
112	        }
113	        let t = deg.to_radians();
114	        let q = add(p, [t.cos() * 1000.0, t.sin() * 1000.0]);
115	        let a = self.pt(p);
116	        let b = self.pt(q);
117	        r9((b[1] - a[1]).atan2(b[0] - a[0]).to_degrees())
118	    }
119	}
120	
121	// ---------------------------------------------------------------- reading values
122	
123	pub fn get_pt(e: &Value, k: &str) -> Option<P> {
124	    let a = e.get(k)?.as_arr()?;
125	    if a.len() < 2 {
126	        return None;
127	    }
128	    Some([a[0].as_f64()?, a[1].as_f64()?])
129	}
