#!/usr/bin/env python3
"""fz_seq.py out.txt n seed: random sequences of editing commands on the fixtures."""
import sys, random, json
out = sys.argv[1]; n = int(sys.argv[2]); seed = int(sys.argv[3])
random.seed(seed)
fx = ['/tmp/edit-agent/fx/all.bimcraft', '/tmp/edit-agent/fx/house.bimcraft', '/tmp/edit-agent/fx/gen/box.bimcraft', '/tmp/edit-agent/fx/gen/chain.bimcraft', '/tmp/edit-agent/fx/gen/del1.bimcraft', '/tmp/edit-agent/fx/gen/node3.bimcraft']
docs = {f: json.load(open(f)) for f in fx}
def rp(): return float(random.randint(-3000, 3000))
def pt(): return [rp(), rp()]
cases = []
for i in range(n):
    f = random.choice(fx)
    els = docs[f]['elements']
    ids = [int(k) for k in els]
    walls = [int(k) for k, e in els.items() if e['category'] == 'wall']
    lines = []
    for _ in range(random.randint(2, 4)):
        k = random.choice(['move', 'move', 'copy', 'rotate', 'mirror', 'delete', 'undo', 'redo', 'align', 'modify', 'purge', 'split', 'corner'])
        sel = random.sample(ids, random.randint(1, min(3, len(ids))))
        if k == 'move':
            lines.append('move {"ids": %s, "by": %s}' % (json.dumps(sel), json.dumps(pt())))
        elif k == 'copy':
            lines.append('copy {"ids": %s, "by": %s}' % (json.dumps(sel), json.dumps([rp() + 20000, rp()])))
        elif k == 'rotate':
            lines.append('rotate {"ids": %s, "about": %s, "angle": %d%s}' % (json.dumps(sel), json.dumps(pt()), random.choice([90, -90, 45, 180, 12]), random.choice(['', ', "copy": true'])))
        elif k == 'mirror':
            lines.append('mirror {"ids": %s, "axis": [%s, %s]%s}' % (json.dumps(sel), json.dumps(pt()), json.dumps(pt()), random.choice(['', ', "copy": true'])))
        elif k == 'delete':
            lines.append('delete {"ids": %s}' % json.dumps(sel))
        elif k == 'undo':
            lines.append('undo {}')
        elif k == 'redo':
            lines.append('redo {}')
        elif k == 'align':
            lines.append('align {"id": %d, "reference": [%s, %s], "line": [%s, %s]}' % (sel[0], json.dumps(pt()), json.dumps(pt()), json.dumps(pt()), json.dumps(pt())))
        elif k == 'modify':
            lines.append('modify {"ids": %s, "base_offset": %d}' % (json.dumps(walls[:2]), random.randint(-500, 500)))
        elif k == 'purge':
            lines.append('purge {}')
        elif k == 'split' and walls:
            w = random.choice(walls); e = els[str(w)]
            s, t = e['start'], e['end']; u = random.uniform(0.2, 0.8)
            lines.append('split {"id": %d, "at": [%s, %s]}' % (w, round(s[0] + (t[0]-s[0])*u, 1), round(s[1] + (t[1]-s[1])*u, 1)))
        elif k == 'corner' and len(walls) >= 2:
            lines.append('corner {"ids": %s}' % json.dumps(random.sample(walls, 2)))
    cases.append('FILE %s\n%s' % (f, '\n'.join(lines)))
open(out, 'w').write('\n---\n'.join(cases) + '\n')
print(len(cases))

